"""Render the discovered role matrix and executable evidence into a reviewable audit report."""
import html,json,pathlib,re
root=pathlib.Path(__file__).resolve().parents[1]
audit=json.loads((root/'docs/qa/platform-role-audit.json').read_text())
result=json.loads((root/'docs/qa/platform-dashboard-results.json').read_text())
esc=html.escape
def scope(name):
 for word,label in [('National','Assigned national unit'),('Regional','Assigned region'),('District','Assigned district'),('Zone','Assigned zone'),('Zonal','Assigned zone'),('Club','Assigned club'),('Guest','Assigned club')]:
  if name.startswith(word):return label+' and permitted descendants'
 return 'Assigned organization branch and permitted descendants'
def experience(r):
 name=r['name']
 if name=='Club Treasurer':return 'Finance dashboard (entity grants still required)'
 if 'members.view' not in r['permissions']:return 'Member portal; committee home when an active relationship exists'
 if name=='Club Secretary':return 'Club operations dashboard'
 for a,b in [('National','National leadership'),('Regional','Regional'),('District','District'),('Zone','Zonal'),('Zonal','Zonal'),('Club','Club')]:
  if name.startswith(a):return b+' dashboard'
 return 'Organization dashboard'
rows=[]
for r in audit['roles']:
 perms=r['permissions'];modules=sorted(set(p.split('.')[0] for p in perms));writes=[p for p in perms if any(k in p for k in ['manage','create','update','approve','assign','post','reconcile','invite','import','issue','publish','collect','link'])]
 reports=[p for p in perms if any(k in p for k in ['reports','export','audit'])]
 r.update(login='/login or / (email/password during local OTP pause)',scope=scope(r['name']),dashboard=experience(r),modules=modules,writeAndApprovalPermissions=writes,reportPermissions=reports,platformDashboard=False)
 rows.append(f'<tr><th>{esc(r["name"])}<small>{len(perms)} grants</small></th><td>{esc(r["scope"])}<small>{esc(r["dashboard"])}</small></td><td>{esc(", ".join(modules))}</td><td>{esc(", ".join(reports) or "None")}</td><td><details><summary>{len(writes)} write/approval grants</summary>{esc(", ".join(writes) or "None")}</details><details><summary>All exact permissions</summary>{esc(", ".join(perms))}</details></td></tr>')
(root/'docs/qa/platform-role-audit.json').write_text(json.dumps(audit,indent=2))
inventory=[]
for path in (root/'server').glob('*.cs'):
 text=path.read_text(encoding='utf-8-sig')
 for m in re.finditer(r'\.Map(Get|Post|Put|Delete|Patch)\(\s*"([^"\n]+)"',text):
  inventory.append(dict(method=m.group(1).upper(),route=m.group(2),source='server/'+path.name,line=text[:m.start()].count('\n')+1))
(root/'docs/qa/access-route-inventory.json').write_text(json.dumps(inventory,indent=2))
cases=''.join(f'<tr><td>{esc(c["scenario"])}</td><td class="{"pass" if c["passed"] else "fail"}">{"PASS" if c["passed"] else "FAIL"}</td></tr>' for c in result['scenarios'])
doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Impact International · dashboard and access audit</title><style>body{font:14px/1.6 system-ui;background:#f4f6fb;color:#142443;margin:0}main{max-width:1400px;margin:auto;padding:30px}header{background:#102143;color:white;padding:30px;border-radius:14px;border-bottom:4px solid #c5a252}h1{margin:0;font-family:Georgia,serif}h2{margin-top:35px}section{background:white;border:1px solid #dce1ec;border-radius:12px;padding:20px;margin:20px 0}table{border-collapse:collapse;width:100%;font-size:12px}th,td{text-align:left;vertical-align:top;border:1px solid #dce1ec;padding:12px}thead{background:#172848;color:white}small{display:block;color:#67768f}summary{cursor:pointer;color:#5c468e}a{color:#49358d}.scroll{overflow:auto}.pass{color:#168044}.fail{color:#b32620}.diagram{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.diagram span{padding:12px;background:#172848;color:white;border-radius:8px}.flag{background:#fcf4dc;padding:14px;border-left:4px solid #c6a24f}li{margin:8px 0}code{background:#f3f1f7;padding:2px 5px}</style><main><header><h1>Impact International</h1><p>Platform Administration Dashboard · authorization audit · 13 November 2026</p></header>
<section><h2>Actual authority and login hierarchy</h2><p>One organization: Impact International. The database contains 17 organizational roles and four committee roles. Platform authority is the server-owned <code>Users.PlatformAdmin</code> flag, independent of workspace role names. An Association Super Admin assignment without that flag does not unlock the premium dashboard.</p><div class="diagram"><span>International</span> → <span>National</span> → <span>Region</span> → <span>District</span> → <span>Zone</span> → <span>Club</span></div><p class="flag">PlatformAdmin flag → all recognized application permissions within the authorized organization context → premium platform dashboard. Otherwise: active owned workspace → role grants + permitted subtree → scoped dashboard. Committee membership adds only dated committee-specific authority.</p><p>Platform Super Admin, Platform Administrator, Organization Owner, Regional Governor and District Governor are not separate stored roles. Chairperson, Vice Chairperson, Member and Secretary are CommitteeRole relationships; Chairperson and Vice Chairperson can manage their committee. These relationships do not grant organizational administrator privileges.</p><p>Entry points: <code>/</code> and <code>/login</code>. Email/password is enabled during the explicitly requested local OTP pause. Server sessions validate expiry, ownership, membership validity, current appointments and the bound domain. Workspace switching replaces active scope; permissions are never combined across assignments. Production OTP defaults remain enabled.</p><p>Members may access the permitted scoped directory, member portal, their own membership and other granted features. Member-level directory permission is not permission to retrieve administrative intelligence. Financial accounting requires explicit financial-entity grants in addition to module permissions.</p></section>
<section><h2>Exact permission matrix</h2><p>Every row below uses actual database permissions. Accessible organizational records are restricted to the assigned subtree; people, personal fields, exports and finances also require their own permission checks. A role name alone grants nothing. All roles share the login entry points above.</p><div class="scroll"><table><thead><tr><th>Actual role</th><th>Scope and dashboard</th><th>Permitted modules</th><th>Reports and exports</th><th>Creation, changes and approvals</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p><a href="qa/platform-role-audit.json">Machine-readable role matrix</a></p></section>
<section><h2>Implementation and metric integrity</h2><p>The existing <code>/api/v1/dashboard</code> endpoint serves route descriptors, scoped aggregates and the platform view. <code>?view=platform</code> and its CSV export require the authenticated platform flag on the server. Forged role identifiers, ancestor scopes and foreign workspaces cannot widen access. The browser URL <code>/app/platform-dashboard</code> has the same server gate.</p><p>The new navy-and-gold dashboard contains ten KPIs, seven priorities, membership and organization trends, event participation, club status, regional/district distributions, membership status, approval pipeline, officer coverage, renewal and engagement indicators, organization/club previews and eight administration links. Search, profile, theme and navigation reuse existing features. The bell links to actual governance priorities; no fabricated unread notification count is displayed.</p><p>Six date modes include custom dates. A repeatable-read database snapshot provides consistent aggregates. Queries project required columns and reuse existing tenant/organization indexes and services; no tables, role categories or competing analytics API were created. Counts use persisted records. Empty activities and undefined denominators are explicitly shown. Current stocks remain current; comparisons describe actual period activity rather than pretending historical stock snapshots exist. Historical renewal cohorts and dedicated approval timestamps are not reconstructed: definitions disclose the operational formulas and UpdatedAt-based turnaround.</p><p>The chart curves are SVG, generated from actual buckets; hover points show dates/counts. Date and distribution controls are interactive. Metric tooltips and the definitions panel disclose the comparison basis. A zero prior baseline shows no invented growth percentage.</p></section>
<section><h2>Vulnerabilities discovered and fixed</h2><ol><li><b>Privilege escalation through delegated roles:</b> assignment creation read a role without loading its grant collection; an empty collection passed the subset check. It now loads grants before checking every requested permission against the delegator's held permissions. Regression tests reject a stronger role and a foreign-scope assignment.</li><li><b>Audit information disclosure:</b> the legacy dashboard returned recent audit records to users with organization.view. It now requires audit.view and scopes results. Member responses contain no administrative aggregates.</li><li><b>Committee policy gaps:</b> relationship-based detail and “mine” listing did not consistently check bound organization domain or active committee role. Both paths now check these constraints. Tests deactivate committee roles and verify that detail, listing and dashboard authority disappear immediately.</li><li><b>Dashboard privilege boundary:</b> premium analytics and CSV export now explicitly require PlatformAdmin; an Association Super Admin label alone is insufficient. Tests verify the distinction for all 17 stored role types.</li></ol></section>
<section><h2>Verification</h2><p>Automated cases: <b>'''+str(result['total'])+'''</b>; passed: <b>'''+str(result['passed'])+'''</b>; failed: <b>'''+str(result['failed'])+'''</b>. Fixtures exist only in the isolated local QA database <code>'''+esc(result['database'])+'''</code>. Existing application records were preserved. Accounts cover every original role plus committee chair/member, a limited delegator and revoked assignment. Credentials are not stored in this report.</p><p>Checks cover login, route selection, branch counts, all-role platform and export denial, forged identifiers, ancestor/foreign scope, protected member APIs, profile tampering, CSRF, anonymous and expired sessions, workspace switching, SQL reconciliation, date boundaries, export audit and committee role revocation.</p><p><a href="qa/platform-dashboard-results.json">Full executable test results</a> · <a href="../tests/platform_dashboard_checks.py">Repeatable authorization suite</a> · <a href="qa/access-route-inventory.json">Source route inventory</a> · <a href="qa/platform-dashboard-browser-results.json">Browser verification</a></p><details><summary>All automated scenarios</summary><table><tbody>'''+cases+'''</tbody></table></details></section>
<section><h2>Files changed for this request</h2><ul><li>server/PlatformDashboard.cs — existing dashboard API, metrics, routing and export authorization.</li><li>server/Program.cs — dashboard handler and role delegation fix.</li><li>server/GovernanceService.cs, CommitteeEndpoints.cs — committee authorization fixes.</li><li>client/src/App.tsx, pages/RoleHome.tsx, pages/Dashboard.tsx — role home, direct route, loading, scoped presentation.</li><li>client/src/pages/PlatformAdminDashboard.tsx and .css — premium dashboard and responsive/theme styles.</li><li>client/public/brand/impact-dashboard-globe.svg — original decorative globe vector.</li><li>client/src/pages/Members.tsx — preserve dashboard status filter on arrival.</li><li>tests/platform_dashboard_checks.py, platform_audit_report.py and docs/qa/platform-* — repeatable checks and audit evidence.</li></ul><p>Earlier uncommitted login and dues changes remain in the working tree; they are not attributed to this dashboard request. No commit or push was made for this request.</p></section>
<section><h2>Limits and outstanding considerations</h2><p>This is a source review and executable authorization audit of dashboard routing, permission delegation, scoped APIs and committee relationships, not a formal proof of every state transition in every application module. The route inventory is a source index, not a claim that every listed handler received a penetration test. Explicit domain-tenant committee guards were reviewed in source; a real multi-domain deployment was not provisioned because the product is a single organization. No production load or 20,000-member benchmark was run. Existing historical data cannot provide exact past status snapshots or approval-decision timestamps; operational comparisons are disclosed. Amazon SES and WhatsApp remain unconfigured as previously requested. No known failing scenario remains in the recorded suite.</p></section></main></html>'''
(root/'docs/platform-dashboard-audit.html').write_text(doc,encoding='utf-8')
print(f'Rendered role matrix, {len(inventory)} route entries and {result["total"]} test results.')
